import { OPERATOR_NAME, SUPPORT_EMAIL } from '@/features/community/moderation-policy';

import OSS from './oss-licenses.json';
import { buildPolicyDocs, type LegalDoc } from './policy-texts';

/**
 * In-app legal texts. Policy texts live in policy-texts.ts (shared with the published web pages);
 * the OSS list is generated by scripts/generate-oss-licenses.mjs from the real app bundle.
 */
export type { LegalDoc };
export type LegalDocId = 'privacy' | 'terms' | 'guidelines' | 'oss' | 'image-credits';

const texts: Record<string, string> = OSS.texts;
const textNumber = new Map(Object.keys(texts).map((id, i) => [id, i + 1]));

export const LEGAL_DOCS: Record<LegalDocId, LegalDoc> = {
  ...buildPolicyDocs({ email: SUPPORT_EMAIL, operator: OPERATOR_NAME }),
  oss: {
    title: '오픈소스 라이선스',
    updatedAt: '2026-10-28',
    sections: [
      { heading: '안내', body: `WearLog 앱에 포함된 오픈소스 소프트웨어 ${OSS.packages.length}개와 글꼴·아이콘의 저작권 표시와 라이선스예요. 각 항목의 "원문 N"은 아래 라이선스 원문 번호예요.` },
      { heading: 'Pretendard (글꼴)', body: 'Copyright (c) 2021, Kil Hyung-jin, with Reserved Font Name Pretendard.\n라이선스: SIL Open Font License 1.1 (https://openfontlicense.org)' },
      { heading: 'Ionicons (아이콘)', body: 'Copyright (c) 2015-present Ionic (http://ionic.io/)\n라이선스: MIT (@expo/vector-icons로 포함)' },
      ...OSS.packages.map((p) => ({
        heading: `${p.name} ${p.version}`,
        body: [...p.copyright, `라이선스: ${p.license}${p.textId ? ` · 원문 ${textNumber.get(p.textId)}` : ''}`].join('\n'),
      })),
      ...Object.entries(texts).map(([id, body]) => ({ heading: `라이선스 원문 ${textNumber.get(id)}`, body })),
    ],
  },
  'image-credits': {
    title: '이미지·데이터 출처',
    updatedAt: '2026-10-28',
    sections: [
      {
        heading: '샘플 옷·착장 사진',
        body: '샘플 옷장·샘플 코디·홈과 커뮤니티의 "샘플" 사진은 WearLog 프로젝트 소유자가 앱에 쓰도록 제공한 이미지예요. 실제 사용자의 게시물이나 판매 상품이 아니며, 상표·로고가 보이는 품목은 넣지 않았어요. 옷 사진은 배경을 지우고 크기를 줄였어요.',
      },
      { heading: '샘플 옷 일러스트', body: '이미지가 없을 때 보이는 옷 실루엣은 WearLog가 직접 그린 벡터 그림이에요.' },
      { heading: '날씨 자료', body: '날씨 정보 출처: 기상청 단기예보 조회서비스(공공데이터포털, 공공누리 제1유형: 출처표시).' },
    ],
  },
};
